/**
 * The seeded-bug corpus and its labels.
 *
 * Each fixture is a `base/` tree, a `head/` tree, and a `label.json` naming
 * either one planted defect or a clean control. The label is the ground truth
 * the scorer matches review findings against, so it is validated strictly:
 * a fixture whose label does not parse is a broken corpus, not a low score.
 *
 * @since 1.0.0
 */
import { $importMetaDirname } from "./labels.platform.js";
import * as $platform from "./labels.platform.js";
import { $join } from "./labels.vibe.platform.js";
export { BUG_CLASSES } from "./labels.platform.js";
export { SeededBugSeverity } from "./labels.platform.js";
export { SeededBugCategory } from "./labels.platform.js";
export { BugClass } from "./labels.platform.js";
export { SeededBugLabel } from "./labels.platform.js";
export { CleanControlLabel } from "./labels.platform.js";
export { PlantedBugLabel } from "./labels.platform.js";
/**
 * Reads every fixture's label, in directory order.
 *
 * The fixture field must equal the directory name: a label that names a
 * different fixture would score one fixture's findings against another's
 * ground truth, which is worse than not scoring at all.
 *
 * @since 1.0.0
 * @category constructors
 */
export function loadCorpus(corpusDir = $join($importMetaDirname(import.meta.url), "corpus")) {
    return $platform.loadCorpus(corpusDir);
}
